    e1 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e1=[b1*n1, 32]
    e2 = rearrange(x, "b n d -> d n b")  # expected-shape: e2=[32, n1, b1]
    e3 = repeat(x, "b n d -> r b n d", r=2)  # expected-shape: e3=[2, b1, n1, 32]
    e4 = reduce(x, "b ... d -> b ...", "mean")  # expected-shape: e4=[b1, n1]
    e5 = rearrange(x, "b ... d -> d b ...")  # expected-shape: e5=[32, b1, n1]
    e6 = rearrange(x, "... n d -> ... (n d)")  # expected-shape: e6=[b1, n1*32]
    e_two = rearrange(x, "... n ... -> ... n")  # expected-shape: e_two=?
    return e0


