    def forward(self, x: Float[Array, "b22 s22 64"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b22, s22, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b22, s22, 64]; k=[b22, s22, 64]; v=[b22, s22, 64]
        q = q.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: q=[b22, s22, 8, 8]
        k = k.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: k=[b22, s22, 8, 8]
        v = v.reshape(x.shape[0], x.shape[1], 8, 8)  # expected-shape: v=[b22, s22, 8, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b22, 8, s22, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b22, 8, 8, s22]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b22, 8, s22, 8]
        scores = q @ k  # expected-shape: scores=[b22, 8, s22, s22]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b22, 8, s22, s22]
        ctx = attn @ v  # expected-shape: ctx=[b22, 8, s22, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b22, s22, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b22, s22, 64]
        out = self.proj(ctx)  # expected-shape: out=[b22, s22, 64]
        out = self.norm(out + x)  # expected-shape: out=[b22, s22, 64]
        return out


