def scan_ema_32(xs: Float[Array, "t32 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t32, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
    scaled = ys / 2.0  # expected-shape: scaled=[t32, 16]
    return last, scaled


def vmap_rows_32(x: Float[Array, "b32 t32 16"], w: Float[Array, "16 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b32, t32, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b32, t32, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b32, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


class Attn33(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_33 = nn.Linear(96, 288)
        self.proj_33 = nn.Linear(96, 96)
        self.norm_33 = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b33 s33 96"]):
        qkv = self.qkv_33(x)  # expected-shape: qkv=[b33, s33, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b33, s33, 96]; k=[b33, s33, 96]; v=[b33, s33, 96]
        q = q.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: q=[b33, s33, 4, 24]
        k = k.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: k=[b33, s33, 4, 24]
        v = v.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: v=[b33, s33, 4, 24]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b33, 4, s33, 24]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b33, 4, 24, s33]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b33, 4, s33, 24]
        scores = q @ k  # expected-shape: scores=[b33, 4, s33, s33]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b33, 4, s33, s33]
        ctx = attn @ v  # expected-shape: ctx=[b33, 4, s33, 24]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b33, s33, 4, 24]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b33, s33, 96]
        out = self.proj_33(ctx)  # expected-shape: out=[b33, s33, 96]
        out = self.norm_33(out + x)  # expected-shape: out=[b33, s33, 96]
        return out


