def scan_ema_42(xs: Float[Array, "t42 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t42, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
    scaled = ys / 2.0  # expected-shape: scaled=[t42, 16]
    return last, scaled


def vmap_rows_42(x: Float[Array, "b42 t42 16"], w: Float[Array, "16 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b42, t42, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b42, t42, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b42, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


def nested_43(x: Float[Array, "b43 n43 d43"], w: Float[Array, "d43 d43"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b43, n43, d43]
    c = x[:, :4]  # expected-shape: c=?
    h = c.sum(axis=1)  # expected-shape: h=?
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b43, n43, 3]; ix=[b43, n43, 3]
    z = y @ w  # expected-shape: z=[b43, n43, d43]
    return y, h, z


class FlaxNet44(fnn.Module):
    @fnn.compact
    def __call__(self, x: Float[Array, "b44 16 16 3"]):
        c = fnn.Conv(features=8, kernel_size=(3, 3))(x)  # expected-shape: c=[b44, 16, 16, 8]
        c = fnn.relu(c)  # expected-shape: c=[b44, 16, 16, 8]
        c = fnn.avg_pool(c, window_shape=(2, 2), strides=(2, 2))  # expected-shape: c=[b44, 8, 8, 8]
        f = c.reshape((c.shape[0], -1))  # expected-shape: f=[b44, 512]
        d = fnn.Dense(features=64)(f)  # expected-shape: d=[b44, 64]
        d = fnn.relu(d)  # expected-shape: d=[b44, 64]
        o = fnn.Dense(features=10)(d)  # expected-shape: o=[b44, 10]
        return o


class SeqModel45(nn.Module):
    def __init__(self):
        super().__init__()
        self.emb = nn.Embedding(500, 32)
        self.gru = nn.GRU(32, 64, batch_first=True)
        self.head = nn.Linear(64, 500)
        self.mha = nn.MultiheadAttention(64, 4)

    def forward(self, ids: Float[Array, "b45 s45"]):
        e = self.emb(ids)  # expected-shape: e=[b45, s45, 32]
        out, _ = self.gru(e)  # expected-shape: out=[b45, s45, 64]
        att, w = self.mha(out, out, out)  # expected-shape: att=[b45, s45, 64]; w=[b45, s45, s45]
        logits = self.head(att)  # expected-shape: logits=[b45, s45, 500]
        pooled = logits.mean(dim=1)  # expected-shape: pooled=[b45, 500]
        last = out[:, -1, :]  # expected-shape: last=[b45, 64]
        tops, idx = logits.topk(5, dim=-1)  # expected-shape: tops=[b45, s45, 5]; idx=[b45, s45, 5]
        return logits


