class EqxBlock49(eqx.Module):
    w1: eqx.nn.Linear
    w2: eqx.nn.Linear
    norm: eqx.nn.LayerNorm

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.w1 = eqx.nn.Linear(64, 128, key=k1)
        self.w2 = eqx.nn.Linear(128, 64, key=k2)
        self.norm = eqx.nn.LayerNorm(64)

    def __call__(self, x: Float[Array, "s49 64"]):
        h = jax.vmap(self.w1)(x)  # expected-shape: h=[s49, 128]
        h = jax.nn.gelu(h)  # expected-shape: h=[s49, 128]
        h = jax.vmap(self.w2)(h)  # expected-shape: h=[s49, 64]
        r = x + h  # expected-shape: r=[s49, 64]
        y = jax.vmap(self.norm)(r)  # expected-shape: y=[s49, 64]
        return y


