def inner_57(t):
    return t * 3.0


def outer_57(t):
    w = inner_57(t)
    s = w.mean(axis=0)
    return s


def lazy_user_57(x: Float[Array, "b57 n57 d57"], y: Float[Array, "n57 d57"]):
    a = outer_57(x)  # expected-shape: a=[n57, d57]
    c = outer_57(y)  # expected-shape: c=[d57]
    e = inner_57(y) + y  # expected-shape: e=[n57, d57]
    return a, c, e


