class ConvNet60(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(3, 8, 3, stride=1, padding=1)
        self.bn0 = nn.BatchNorm2d(8)
        self.conv1 = nn.Conv2d(8, 32, 3, stride=1, padding=1)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 64, 5, stride=1, padding=2)
        self.bn2 = nn.BatchNorm2d(64)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(576, 100)

    def forward(self, x: Float[Array, "b60 3 28 28"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b60, 8, 28, 28]
        n0 = self.bn0(c0)  # expected-shape: n0=[b60, 8, 28, 28]
        r0 = F.relu(n0)  # expected-shape: r0=[b60, 8, 28, 28]
        p0 = self.pool(r0)  # expected-shape: p0=[b60, 8, 14, 14]
        c1 = self.conv1(p0)  # expected-shape: c1=[b60, 32, 14, 14]
        n1 = self.bn1(c1)  # expected-shape: n1=[b60, 32, 14, 14]
        r1 = F.relu(n1)  # expected-shape: r1=[b60, 32, 14, 14]
        p1 = self.pool(r1)  # expected-shape: p1=[b60, 32, 7, 7]
        c2 = self.conv2(p1)  # expected-shape: c2=[b60, 64, 7, 7]
        n2 = self.bn2(c2)  # expected-shape: n2=[b60, 64, 7, 7]
        r2 = F.relu(n2)  # expected-shape: r2=[b60, 64, 7, 7]
        p2 = self.pool(r2)  # expected-shape: p2=[b60, 64, 3, 3]
        f = p2.flatten(1)  # expected-shape: f=[b60, 576]
        logits = self.fc(f)  # expected-shape: logits=[b60, 100]
        return logits


