class EqxBlock64(eqx.Module):
    w1: eqx.nn.Linear
    w2: eqx.nn.Linear
    norm: eqx.nn.LayerNorm

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.w1 = eqx.nn.Linear(64, 128, key=k1)
        self.w2 = eqx.nn.Linear(128, 64, key=k2)
        self.norm = eqx.nn.LayerNorm(64)

    def __call__(self, x: Float[Array, "s64 64"]):
        h = jax.vmap(self.w1)(x)  # expected-shape: h=[s64, 128]
        h = jax.nn.gelu(h)  # expected-shape: h=[s64, 128]
        h = jax.vmap(self.w2)(h)  # expected-shape: h=[s64, 64]
        r = x + h  # expected-shape: r=[s64, 64]
        y = jax.vmap(self.norm)(r)  # expected-shape: y=[s64, 64]
        return y


class EqxModel64(eqx.Module):
    blk: EqxBlock64
    head: eqx.nn.Linear

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.blk = EqxBlock64(k1)
        self.head = eqx.nn.Linear(64, 10, key=k2)

    def __call__(self, x: Float[Array, "s64 64"]):
        h = self.blk(x)  # expected-shape: h=[s64, 64]
        p = jax.vmap(self.head)(h)  # expected-shape: p=[s64, 10]
        m = p.mean(axis=0)  # expected-shape: m=[10]
        return m


