        c = fnn.relu(c)  # expected-shape: c=[b65, 32, 32, 16]
        c = fnn.avg_pool(c, window_shape=(2, 2), strides=(2, 2))  # expected-shape: c=[b65, 16, 16, 16]
        f = c.reshape((c.shape[0], -1))  # expected-shape: f=[b65, 4096]
        d = fnn.Dense(features=64)(f)  # expected-shape: d=[b65, 64]
        d = fnn.relu(d)  # expected-shape: d=[b65, 64]
        o = fnn.Dense(features=10)(d)  # expected-shape: o=[b65, 10]
