def long_chain_67(x: Float[Array, "b67 16 d67"]):
    v0 = jax.nn.softmax(x, axis=-1)  # expected-shape: v0=[b67, 16, d67]
    v1 = v0[:, 0]
    v2 = v1.T
    v3 = v2.T
    v4 = v3 * 3
    v5 = v4.T  # expected-shape: v5=[d67, b67]
    v6 = jnp.exp(v5)
    v7 = v6 * 2.0
    v8 = v7 * 2.0
    v9 = jnp.tanh(v8)
    v10 = v9 + v7  # expected-shape: v10=[d67, b67]
    v11 = v10.T
    v12 = v11 * 2.0
    v13 = v12 + v1
    v14 = jnp.swapaxes(v13, 0, 1)
