    v21 = v20 + v7
    v22 = v21.T
    v23 = v22 + v1
    v24 = v23 * 3
    v25 = jnp.expand_dims(v24, axis=1)  # expected-shape: v25=[b67, 1, d67]
    v26 = v25 * 1.5
    v27 = v26.sum(axis=1)
    v28 = jnp.expand_dims(v27, axis=0)
    v29 = jnp.exp(v28)
    v30 = jnp.concatenate([v29, v29], axis=0)  # expected-shape: v30=[2, b67, d67]
    v31 = v30.mean(axis=2)
    v32 = jnp.exp(v31)
    v33 = jnp.abs(v32)
    v34 = jnp.swapaxes(v33, 0, 1)
    v35 = jnp.expand_dims(v34, axis=0)  # expected-shape: v35=[1, b67, 2]
