class Config68:
    dim: int = 96
    heads: int = 4
    name: str = "cfg"

    @property
    def head_dim(self) -> int:
        return self.dim // self.heads


def scalar_math_68(a: float, b: int = 68) -> float:
    """Plain Python with no tensors: the analyzer must skip it."""
    total = 0.0
    for k in range(b):
        total += math.sqrt(k + a) * (k % 3)
    values = [k * 2 for k in range(10) if k % 2 == 0]
    table = {k: v for k, v in zip(range(5), values)}
    if total > 10 and len(table) > 2:
        total = -total
    return total


def branchy_69(x: Float[Array, "b69 n69 d69"], y: Float[Array, "b69 n69 d69"], flag69: bool):
    z = x + y  # expected-shape: z=[b69, n69, d69]
    if flag69:
        w = z.sum(axis=-1)  # expected-shape: w=[b69, n69]
    elif not flag69:
        w = z.mean(axis=1)  # expected-shape: w=[b69, d69]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b69, n69]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b69, n69, d69]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n69, d69]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n69, d69]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


