class SeqModel72(nn.Module):
    def __init__(self):
        super().__init__()
        self.emb = nn.Embedding(1000, 128)
        self.gru = nn.GRU(128, 128, batch_first=True)
        self.head = nn.Linear(128, 1000)
        self.mha = nn.MultiheadAttention(128, 4)

    def forward(self, ids: Float[Array, "b72 s72"]):
        e = self.emb(ids)  # expected-shape: e=[b72, s72, 128]
        out, _ = self.gru(e)  # expected-shape: out=[b72, s72, 128]
        att, w = self.mha(out, out, out)  # expected-shape: att=[b72, s72, 128]; w=[b72, s72, s72]
        logits = self.head(att)  # expected-shape: logits=[b72, s72, 1000]
        pooled = logits.mean(dim=1)  # expected-shape: pooled=[b72, 1000]
        last = out[:, -1, :]  # expected-shape: last=[b72, 128]
        tops, idx = logits.topk(5, dim=-1)  # expected-shape: tops=[b72, s72, 5]; idx=[b72, s72, 5]
        return logits


def cross_73(x: Float[Array, "b73 d73"], w: Float[Array, "d73 k73"], seq: Float[Array, "b73 n73 d73"]):
    a = norm_rows_13(x)  # expected-shape: a=[b73, d73]
    p = project_13(a, w)  # expected-shape: p=[b73, k73]
    c = pool_seq_13(seq)  # expected-shape: c=[b73, d73]
    q = project_13(c, w)  # expected-shape: q=[b73, k73]
    sc = attend_13(seq, seq)  # expected-shape: sc=[b73, n73, n73]
    s2 = scale_rows_13(sc)  # expected-shape: s2=[b73, n73, n73]
    return p, q, s2


class ConvNet74(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(3, 16, 3, stride=1, padding=1)
        self.bn0 = nn.BatchNorm2d(16)
        self.conv1 = nn.Conv2d(16, 32, 3, stride=1, padding=1)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 64, 5, stride=1, padding=0)
        self.bn2 = nn.BatchNorm2d(64)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(2304, 10)

    def forward(self, x: Float[Array, "b74 3 64 64"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b74, 16, 64, 64]
        n0 = self.bn0(c0)  # expected-shape: n0=[b74, 16, 64, 64]
        r0 = F.relu(n0)  # expected-shape: r0=[b74, 16, 64, 64]
        p0 = self.pool(r0)  # expected-shape: p0=[b74, 16, 32, 32]
        c1 = self.conv1(p0)  # expected-shape: c1=[b74, 32, 32, 32]
        n1 = self.bn1(c1)  # expected-shape: n1=[b74, 32, 32, 32]
        r1 = F.relu(n1)  # expected-shape: r1=[b74, 32, 32, 32]
        p1 = self.pool(r1)  # expected-shape: p1=[b74, 32, 16, 16]
        c2 = self.conv2(p1)  # expected-shape: c2=[b74, 64, 12, 12]
        n2 = self.bn2(c2)  # expected-shape: n2=[b74, 64, 12, 12]
        r2 = F.relu(n2)  # expected-shape: r2=[b74, 64, 12, 12]
        p2 = self.pool(r2)  # expected-shape: p2=[b74, 64, 6, 6]
        f = p2.flatten(1)  # expected-shape: f=[b74, 2304]
        logits = self.fc(f)  # expected-shape: logits=[b74, 10]
        return logits


class FlaxNet75(fnn.Module):
    @fnn.compact
    def __call__(self, x: Float[Array, "b75 32 32 1"]):
        c = fnn.Conv(features=32, kernel_size=(3, 3))(x)  # expected-shape: c=[b75, 32, 32, 32]
        c = fnn.relu(c)  # expected-shape: c=[b75, 32, 32, 32]
        c = fnn.avg_pool(c, window_shape=(2, 2), strides=(2, 2))  # expected-shape: c=[b75, 16, 16, 32]
        f = c.reshape((c.shape[0], -1))  # expected-shape: f=[b75, 8192]
        d = fnn.Dense(features=64)(f)  # expected-shape: d=[b75, 64]
        d = fnn.relu(d)  # expected-shape: d=[b75, 64]
        o = fnn.Dense(features=10)(d)  # expected-shape: o=[b75, 10]
        return o


class EqxBlock76(eqx.Module):
    w1: eqx.nn.Linear
    w2: eqx.nn.Linear
    norm: eqx.nn.LayerNorm

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.w1 = eqx.nn.Linear(64, 128, key=k1)
        self.w2 = eqx.nn.Linear(128, 64, key=k2)
        self.norm = eqx.nn.LayerNorm(64)

    def __call__(self, x: Float[Array, "s76 64"]):
        h = jax.vmap(self.w1)(x)  # expected-shape: h=[s76, 128]
        h = jax.nn.gelu(h)  # expected-shape: h=[s76, 128]
        h = jax.vmap(self.w2)(h)  # expected-shape: h=[s76, 64]
        r = x + h  # expected-shape: r=[s76, 64]
        y = jax.vmap(self.norm)(r)  # expected-shape: y=[s76, 64]
        return y


