    e3 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e3=[b78, 4, n78, 4]
    e4 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e4=[b78*n78, 16]
    e5 = reduce(x, "b n d -> n", "sum")  # expected-shape: e5=[n78]
    e6 = rearrange(x, "... n d -> ... (n d)")  # expected-shape: e6=[b78, n78*16]
