def einops_soup_83(x: Float[Array, "b83 n83 32"]):
    e0 = rearrange(x, "b n d -> d n b")  # expected-shape: e0=[32, n83, b83]
    e1 = reduce(x, "b ... d -> b ...", "mean")  # expected-shape: e1=[b83, n83]
    e2 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e2=[b83, 4, n83, 8]
    e3 = rearrange(x, "b ... d -> d b ...")  # expected-shape: e3=[32, b83, n83]
    e4 = repeat(x, "b ... -> b ... k", k=3)  # expected-shape: e4=[b83, n83, 32, 3]
    e5 = reduce(x, "b n d -> b d", "mean")  # expected-shape: e5=[b83, 32]
