def scan_ema_84(xs: Float[Array, "t84 8"], h0: Float[Array, "8"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[8]; ys=[t84, 8]
    total = ys.sum(axis=0)  # expected-shape: total=[8]
    scaled = ys / 2.0  # expected-shape: scaled=[t84, 8]
    return last, scaled


def vmap_rows_84(x: Float[Array, "b84 t84 8"], w: Float[Array, "8 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b84, t84, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b84, t84, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b84, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


