class Attn116(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b116 s116 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b116, s116, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b116, s116, 96]; k=[b116, s116, 96]; v=[b116, s116, 96]
        q = q.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: q=[b116, s116, 8, 12]
        k = k.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: k=[b116, s116, 8, 12]
        v = v.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: v=[b116, s116, 8, 12]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b116, 8, s116, 12]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b116, 8, 12, s116]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b116, 8, s116, 12]
        scores = q @ k  # expected-shape: scores=[b116, 8, s116, s116]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b116, 8, s116, s116]
        ctx = attn @ v  # expected-shape: ctx=[b116, 8, s116, 12]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b116, s116, 8, 12]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b116, s116, 96]
        out = self.proj(ctx)  # expected-shape: out=[b116, s116, 96]
        out = self.norm(out + x)  # expected-shape: out=[b116, s116, 96]
        return out


class AttnBlock116(Attn116):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(96, 384)
        self.fc2 = nn.Linear(384, 96)

    def forward(self, x: Float[Array, "b116 s116 96"]):
        h = self.norm(x)  # expected-shape: h=[b116, s116, 96]
