def scalar_math_137(a: float, b: int = 137) -> float:
    """Plain Python with no tensors: the analyzer must skip it."""
    total = 0.0
    for k in range(b):
        total += math.sqrt(k + a) * (k % 3)
    values = [k * 2 for k in range(10) if k % 2 == 0]
    table = {k: v for k, v in zip(range(5), values)}
    if total > 10 and len(table) > 2:
        total = -total
    return total


def scan_ema_138(xs: Float[Array, "t138 32"], h0: Float[Array, "32"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[32]; ys=[t138, 32]
    total = ys.sum(axis=0)  # expected-shape: total=[32]
    scaled = ys / 2.0  # expected-shape: scaled=[t138, 32]
    return last, scaled


def vmap_rows_138(x: Float[Array, "b138 t138 32"], w: Float[Array, "32 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b138, t138, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b138, t138, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b138, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


def nested_139(x: Float[Array, "b139 n139 d139"], w: Float[Array, "d139 d139"]):
    def level1(t):
        u = t * 2.0

        def level2(v):
            return v + 1.0

        return level2(u)

    y = level1(x)  # expected-shape: y=[b139, n139, d139]
    c = x[:, :4]  # expected-shape: c=?
    h = c.sum(axis=1)  # expected-shape: h=?
    top, ix = jax.lax.top_k(y, 3)  # expected-shape: top=[b139, n139, 3]; ix=[b139, n139, 3]
    z = y @ w  # expected-shape: z=[b139, n139, d139]
    return y, h, z


