class Attn141(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_141 = nn.Linear(32, 96)
        self.proj_141 = nn.Linear(32, 32)
        self.norm_141 = nn.LayerNorm(32)

    def forward(self, x: Float[Array, "b141 s141 32"]):
        qkv = self.qkv_141(x)  # expected-shape: qkv=[b141, s141, 96]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b141, s141, 32]; k=[b141, s141, 32]; v=[b141, s141, 32]
        q = q.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: q=[b141, s141, 2, 16]
        k = k.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: k=[b141, s141, 2, 16]
        v = v.reshape(x.shape[0], x.shape[1], 2, 16)  # expected-shape: v=[b141, s141, 2, 16]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b141, 2, s141, 16]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b141, 2, 16, s141]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b141, 2, s141, 16]
        scores = q @ k  # expected-shape: scores=[b141, 2, s141, s141]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b141, 2, s141, s141]
        ctx = attn @ v  # expected-shape: ctx=[b141, 2, s141, 16]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b141, s141, 2, 16]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 32)  # expected-shape: ctx=[b141, s141, 32]
        out = self.proj_141(ctx)  # expected-shape: out=[b141, s141, 32]
        out = self.norm_141(out + x)  # expected-shape: out=[b141, s141, 32]
        return out


class AttnBlock141(Attn141):
    def __init__(self):
        super().__init__()
        self.fc1_141 = nn.Linear(32, 128)
        self.fc2_141 = nn.Linear(128, 32)

    def forward(self, x: Float[Array, "b141 s141 32"]):
        h = self.norm_141(x)  # expected-shape: h=[b141, s141, 32]
        h = self.fc1_141(h)  # expected-shape: h=[b141, s141, 128]
        h = F.gelu(h)  # expected-shape: h=[b141, s141, 128]
        h = self.fc2_141(h)  # expected-shape: h=[b141, s141, 32]
        qkv2 = self.qkv_141(h)  # expected-shape: qkv2=[b141, s141, 96]
        o = self.proj_141(h) + x  # expected-shape: o=[b141, s141, 32]
        return o


