def branchy_144(x: Float[Array, "b144 n144 d144"], y: Float[Array, "b144 n144 d144"], flag144: bool):
    z = x + y  # expected-shape: z=[b144, n144, d144]
    if flag144:
        w = z.sum(axis=-1)  # expected-shape: w=[b144, n144]
    elif not flag144:
        w = z.mean(axis=1)  # expected-shape: w=[b144, d144]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b144, n144]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b144, n144, d144]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n144, d144]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n144, d144]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


