        ctx = attn @ v  # expected-shape: ctx=[b145, 8, s145, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b145, s145, 8, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b145, s145, 64]
        out = self.proj_145(ctx)  # expected-shape: out=[b145, s145, 64]
        out = self.norm_145(out + x)  # expected-shape: out=[b145, s145, 64]
        return out


