class Attn158(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b158 s158 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b158, s158, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b158, s158, 96]; k=[b158, s158, 96]; v=[b158, s158, 96]
        q = q.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: q=[b158, s158, 8, 12]
        k = k.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: k=[b158, s158, 8, 12]
        v = v.reshape(x.shape[0], x.shape[1], 8, 12)  # expected-shape: v=[b158, s158, 8, 12]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b158, 8, s158, 12]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b158, 8, 12, s158]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b158, 8, s158, 12]
        scores = q @ k  # expected-shape: scores=[b158, 8, s158, s158]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b158, 8, s158, s158]
        ctx = attn @ v  # expected-shape: ctx=[b158, 8, s158, 12]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b158, s158, 8, 12]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b158, s158, 96]
        out = self.proj(ctx)  # expected-shape: out=[b158, s158, 96]
        out = self.norm(out + x)  # expected-shape: out=[b158, s158, 96]
        return out


