class ConvNet167(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(1, 16, 5, stride=1, padding=0)
        self.bn0 = nn.BatchNorm2d(16)
        self.conv1 = nn.Conv2d(16, 48, 5, stride=1, padding=2)
        self.bn1 = nn.BatchNorm2d(48)
        self.conv2 = nn.Conv2d(48, 96, 5, stride=1, padding=2)
        self.bn2 = nn.BatchNorm2d(96)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(864, 10)

    def forward(self, x: Float[Array, "b167 1 32 32"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b167, 16, 28, 28]
        n0 = self.bn0(c0)  # expected-shape: n0=[b167, 16, 28, 28]
        r0 = F.relu(n0)  # expected-shape: r0=[b167, 16, 28, 28]
        p0 = self.pool(r0)  # expected-shape: p0=[b167, 16, 14, 14]
        c1 = self.conv1(p0)  # expected-shape: c1=[b167, 48, 14, 14]
        n1 = self.bn1(c1)  # expected-shape: n1=[b167, 48, 14, 14]
        r1 = F.relu(n1)  # expected-shape: r1=[b167, 48, 14, 14]
        p1 = self.pool(r1)  # expected-shape: p1=[b167, 48, 7, 7]
        c2 = self.conv2(p1)  # expected-shape: c2=[b167, 96, 7, 7]
        n2 = self.bn2(c2)  # expected-shape: n2=[b167, 96, 7, 7]
        r2 = F.relu(n2)  # expected-shape: r2=[b167, 96, 7, 7]
        p2 = self.pool(r2)  # expected-shape: p2=[b167, 96, 3, 3]
        f = p2.flatten(1)  # expected-shape: f=[b167, 864]
        logits = self.fc(f)  # expected-shape: logits=[b167, 10]
        return logits


def scan_ema_168(xs: Float[Array, "t168 8"], h0: Float[Array, "8"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[8]; ys=[t168, 8]
    total = ys.sum(axis=0)  # expected-shape: total=[8]
    scaled = ys / 2.0  # expected-shape: scaled=[t168, 8]
    return last, scaled


def vmap_rows_168(x: Float[Array, "b168 t168 8"], w: Float[Array, "8 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b168, t168, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b168, t168, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b168, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


