def scan_ema_174(xs: Float[Array, "t174 8"], h0: Float[Array, "8"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[8]; ys=[t174, 8]
    total = ys.sum(axis=0)  # expected-shape: total=[8]
    scaled = ys / 2.0  # expected-shape: scaled=[t174, 8]
    return last, scaled


def vmap_rows_174(x: Float[Array, "b174 t174 8"], w: Float[Array, "8 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b174, t174, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b174, t174, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b174, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


def inner_175(t):
    return t * 3.0


def outer_175(t):
    w = inner_175(t)
    s = w.mean(axis=0)
    return s


def lazy_user_175(x: Float[Array, "b175 n175 d175"], y: Float[Array, "n175 d175"]):
    a = outer_175(x)  # expected-shape: a=[n175, d175]
    c = outer_175(y)  # expected-shape: c=[d175]
    e = inner_175(y) + y  # expected-shape: e=[n175, d175]
    return a, c, e


