class Attn188(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(32, 96)
        self.proj = nn.Linear(32, 32)
        self.norm = nn.LayerNorm(32)

    def forward(self, x: Float[Array, "b188 s188 32"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b188, s188, 96]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b188, s188, 32]; k=[b188, s188, 32]; v=[b188, s188, 32]
        q = q.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: q=[b188, s188, 8, 4]
        k = k.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: k=[b188, s188, 8, 4]
        v = v.reshape(x.shape[0], x.shape[1], 8, 4)  # expected-shape: v=[b188, s188, 8, 4]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b188, 8, s188, 4]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b188, 8, 4, s188]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b188, 8, s188, 4]
        scores = q @ k  # expected-shape: scores=[b188, 8, s188, s188]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b188, 8, s188, s188]
        ctx = attn @ v  # expected-shape: ctx=[b188, 8, s188, 4]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b188, s188, 8, 4]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 32)  # expected-shape: ctx=[b188, s188, 32]
        out = self.proj(ctx)  # expected-shape: out=[b188, s188, 32]
        out = self.norm(out + x)  # expected-shape: out=[b188, s188, 32]
        return out


