class Attn196(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv = nn.Linear(96, 288)
        self.proj = nn.Linear(96, 96)
        self.norm = nn.LayerNorm(96)

    def forward(self, x: Float[Array, "b196 s196 96"]):
        qkv = self.qkv(x)  # expected-shape: qkv=[b196, s196, 288]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b196, s196, 96]; k=[b196, s196, 96]; v=[b196, s196, 96]
        q = q.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: q=[b196, s196, 4, 24]
        k = k.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: k=[b196, s196, 4, 24]
        v = v.reshape(x.shape[0], x.shape[1], 4, 24)  # expected-shape: v=[b196, s196, 4, 24]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b196, 4, s196, 24]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b196, 4, 24, s196]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b196, 4, s196, 24]
        scores = q @ k  # expected-shape: scores=[b196, 4, s196, s196]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b196, 4, s196, s196]
        ctx = attn @ v  # expected-shape: ctx=[b196, 4, s196, 24]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b196, s196, 4, 24]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 96)  # expected-shape: ctx=[b196, s196, 96]
        out = self.proj(ctx)  # expected-shape: out=[b196, s196, 96]
        out = self.norm(out + x)  # expected-shape: out=[b196, s196, 96]
        return out


