        p0 = self.pool(r0)  # expected-shape: p0=[b214, 24, 32, 32]
        c1 = self.conv1(p0)  # expected-shape: c1=[b214, 48, 32, 32]
        n1 = self.bn1(c1)  # expected-shape: n1=[b214, 48, 32, 32]
        r1 = F.relu(n1)  # expected-shape: r1=[b214, 48, 32, 32]
        p1 = self.pool(r1)  # expected-shape: p1=[b214, 48, 16, 16]
        c2 = self.conv2(p1)  # expected-shape: c2=[b214, 64, 16, 16]
        n2 = self.bn2(c2)  # expected-shape: n2=[b214, 64, 16, 16]
        r2 = F.relu(n2)  # expected-shape: r2=[b214, 64, 16, 16]
        p2 = self.pool(r2)  # expected-shape: p2=[b214, 64, 8, 8]
