    def forward(self, x: Float[Array, "b243 s243 128"]):
        qkv = self.qkv_243(x)  # expected-shape: qkv=[b243, s243, 384]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b243, s243, 128]; k=[b243, s243, 128]; v=[b243, s243, 128]
        q = q.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: q=[b243, s243, 2, 64]
        k = k.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: k=[b243, s243, 2, 64]
        v = v.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: v=[b243, s243, 2, 64]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b243, 2, s243, 64]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b243, 2, 64, s243]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b243, 2, s243, 64]
