        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b243, 2, s243, s243]
        ctx = attn @ v  # expected-shape: ctx=[b243, 2, s243, 64]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b243, s243, 2, 64]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 128)  # expected-shape: ctx=[b243, s243, 128]
        out = self.proj_243(ctx)  # expected-shape: out=[b243, s243, 128]
        out = self.norm_243(out + x)  # expected-shape: out=[b243, s243, 128]
        return out


