class SeqModel246(nn.Module):
    def __init__(self):
        super().__init__()
        self.emb = nn.Embedding(5000, 32)
        self.gru = nn.GRU(32, 128, batch_first=True)
        self.head = nn.Linear(128, 5000)
        self.mha = nn.MultiheadAttention(128, 4)

    def forward(self, ids: Float[Array, "b246 s246"]):
        e = self.emb(ids)  # expected-shape: e=[b246, s246, 32]
        out, _ = self.gru(e)  # expected-shape: out=[b246, s246, 128]
        att, w = self.mha(out, out, out)  # expected-shape: att=[b246, s246, 128]; w=[b246, s246, s246]
        logits = self.head(att)  # expected-shape: logits=[b246, s246, 5000]
        pooled = logits.mean(dim=1)  # expected-shape: pooled=[b246, 5000]
        last = out[:, -1, :]  # expected-shape: last=[b246, 128]
        tops, idx = logits.topk(5, dim=-1)  # expected-shape: tops=[b246, s246, 5]; idx=[b246, s246, 5]
        return logits


def einops_soup_247(x: Float[Array, "b247 n247 16"]):
    e0 = repeat(x, "b ... -> b ... k", k=3)  # expected-shape: e0=[b247, n247, 16, 3]
    e1 = rearrange(x, "... n d -> ... (n d)")  # expected-shape: e1=[b247, n247*16]
    e2 = reduce(x, "b n d -> b d", "mean")  # expected-shape: e2=[b247, 16]
    e3 = rearrange(x, "b n d -> b (n d)")  # expected-shape: e3=[b247, n247*16]
    e4 = repeat(x, "b n d -> r b n d", r=2)  # expected-shape: e4=[2, b247, n247, 16]
    e5 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e5=[b247*n247, 16]
    e6 = rearrange(x, "b n d -> d n b")  # expected-shape: e6=[16, n247, b247]
    e_two = rearrange(x, "... n ... -> ... n")  # expected-shape: e_two=?
    return e0


