class Attn261(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_261 = nn.Linear(64, 192)
        self.proj_261 = nn.Linear(64, 64)
        self.norm_261 = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b261 s261 64"]):
        qkv = self.qkv_261(x)  # expected-shape: qkv=[b261, s261, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b261, s261, 64]; k=[b261, s261, 64]; v=[b261, s261, 64]
        q = q.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: q=[b261, s261, 2, 32]
        k = k.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: k=[b261, s261, 2, 32]
        v = v.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: v=[b261, s261, 2, 32]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b261, 2, s261, 32]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b261, 2, 32, s261]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b261, 2, s261, 32]
        scores = q @ k  # expected-shape: scores=[b261, 2, s261, s261]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b261, 2, s261, s261]
        ctx = attn @ v  # expected-shape: ctx=[b261, 2, s261, 32]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b261, s261, 2, 32]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b261, s261, 64]
        out = self.proj_261(ctx)  # expected-shape: out=[b261, s261, 64]
        out = self.norm_261(out + x)  # expected-shape: out=[b261, s261, 64]
        return out


class AttnBlock261(Attn261):
    def __init__(self):
        super().__init__()
        self.fc1_261 = nn.Linear(64, 256)
        self.fc2_261 = nn.Linear(256, 64)

    def forward(self, x: Float[Array, "b261 s261 64"]):
        h = self.norm_261(x)  # expected-shape: h=[b261, s261, 64]
        h = self.fc1_261(h)  # expected-shape: h=[b261, s261, 256]
