class ConvNet300(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(1, 24, 5, stride=1, padding=0)
        self.bn0 = nn.BatchNorm2d(24)
        self.conv1 = nn.Conv2d(24, 32, 3, stride=2, padding=1)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 96, 3, stride=2, padding=1)
        self.bn2 = nn.BatchNorm2d(96)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(96, 10)

    def forward(self, x: Float[Array, "b300 1 32 32"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b300, 24, 28, 28]
        n0 = self.bn0(c0)  # expected-shape: n0=[b300, 24, 28, 28]
        r0 = F.relu(n0)  # expected-shape: r0=[b300, 24, 28, 28]
        p0 = self.pool(r0)  # expected-shape: p0=[b300, 24, 14, 14]
        c1 = self.conv1(p0)  # expected-shape: c1=[b300, 32, 7, 7]
        n1 = self.bn1(c1)  # expected-shape: n1=[b300, 32, 7, 7]
        r1 = F.relu(n1)  # expected-shape: r1=[b300, 32, 7, 7]
        p1 = self.pool(r1)  # expected-shape: p1=[b300, 32, 3, 3]
        c2 = self.conv2(p1)  # expected-shape: c2=[b300, 96, 2, 2]
        n2 = self.bn2(c2)  # expected-shape: n2=[b300, 96, 2, 2]
        r2 = F.relu(n2)  # expected-shape: r2=[b300, 96, 2, 2]
        p2 = self.pool(r2)  # expected-shape: p2=[b300, 96, 1, 1]
        f = p2.flatten(1)  # expected-shape: f=[b300, 96]
        logits = self.fc(f)  # expected-shape: logits=[b300, 10]
        return logits


class Attn301(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_301 = nn.Linear(32, 96)
        self.proj_301 = nn.Linear(32, 32)
        self.norm_301 = nn.LayerNorm(32)

    def forward(self, x: Float[Array, "b301 s301 32"]):
        qkv = self.qkv_301(x)  # expected-shape: qkv=[b301, s301, 96]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b301, s301, 32]; k=[b301, s301, 32]; v=[b301, s301, 32]
        q = q.reshape(x.shape[0], x.shape[1], 4, 8)  # expected-shape: q=[b301, s301, 4, 8]
        k = k.reshape(x.shape[0], x.shape[1], 4, 8)  # expected-shape: k=[b301, s301, 4, 8]
        v = v.reshape(x.shape[0], x.shape[1], 4, 8)  # expected-shape: v=[b301, s301, 4, 8]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b301, 4, s301, 8]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b301, 4, 8, s301]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b301, 4, s301, 8]
        scores = q @ k  # expected-shape: scores=[b301, 4, s301, s301]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b301, 4, s301, s301]
        ctx = attn @ v  # expected-shape: ctx=[b301, 4, s301, 8]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b301, s301, 4, 8]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 32)  # expected-shape: ctx=[b301, s301, 32]
        out = self.proj_301(ctx)  # expected-shape: out=[b301, s301, 32]
        out = self.norm_301(out + x)  # expected-shape: out=[b301, s301, 32]
        return out


class AttnBlock301(Attn301):
    def __init__(self):
        super().__init__()
        self.fc1_301 = nn.Linear(32, 128)
        self.fc2_301 = nn.Linear(128, 32)

    def forward(self, x: Float[Array, "b301 s301 32"]):
        h = self.norm_301(x)  # expected-shape: h=[b301, s301, 32]
        h = self.fc1_301(h)  # expected-shape: h=[b301, s301, 128]
        h = F.gelu(h)  # expected-shape: h=[b301, s301, 128]
