def scalar_math_305(a: float, b: int = 305) -> float:
    """Plain Python with no tensors: the analyzer must skip it."""
    total = 0.0
    for k in range(b):
        total += math.sqrt(k + a) * (k % 3)
    values = [k * 2 for k in range(10) if k % 2 == 0]
    table = {k: v for k, v in zip(range(5), values)}
    if total > 10 and len(table) > 2:
        total = -total
    return total


