class Attn307(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_307 = nn.Linear(128, 384)
        self.proj_307 = nn.Linear(128, 128)
        self.norm_307 = nn.LayerNorm(128)

    def forward(self, x: Float[Array, "b307 s307 128"]):
        qkv = self.qkv_307(x)  # expected-shape: qkv=[b307, s307, 384]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b307, s307, 128]; k=[b307, s307, 128]; v=[b307, s307, 128]
        q = q.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: q=[b307, s307, 8, 16]
        k = k.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: k=[b307, s307, 8, 16]
        v = v.reshape(x.shape[0], x.shape[1], 8, 16)  # expected-shape: v=[b307, s307, 8, 16]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b307, 8, s307, 16]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b307, 8, 16, s307]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b307, 8, s307, 16]
        scores = q @ k  # expected-shape: scores=[b307, 8, s307, s307]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b307, 8, s307, s307]
        ctx = attn @ v  # expected-shape: ctx=[b307, 8, s307, 16]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b307, s307, 8, 16]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 128)  # expected-shape: ctx=[b307, s307, 128]
        out = self.proj_307(ctx)  # expected-shape: out=[b307, s307, 128]
        out = self.norm_307(out + x)  # expected-shape: out=[b307, s307, 128]
        return out


