class Attn349(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_349 = nn.Linear(128, 384)
        self.proj_349 = nn.Linear(128, 128)
        self.norm_349 = nn.LayerNorm(128)

    def forward(self, x: Float[Array, "b349 s349 128"]):
        qkv = self.qkv_349(x)  # expected-shape: qkv=[b349, s349, 384]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b349, s349, 128]; k=[b349, s349, 128]; v=[b349, s349, 128]
        q = q.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: q=[b349, s349, 2, 64]
        k = k.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: k=[b349, s349, 2, 64]
        v = v.reshape(x.shape[0], x.shape[1], 2, 64)  # expected-shape: v=[b349, s349, 2, 64]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b349, 2, s349, 64]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b349, 2, 64, s349]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b349, 2, s349, 64]
        scores = q @ k  # expected-shape: scores=[b349, 2, s349, s349]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b349, 2, s349, s349]
        ctx = attn @ v  # expected-shape: ctx=[b349, 2, s349, 64]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b349, s349, 2, 64]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 128)  # expected-shape: ctx=[b349, s349, 128]
        out = self.proj_349(ctx)  # expected-shape: out=[b349, s349, 128]
        out = self.norm_349(out + x)  # expected-shape: out=[b349, s349, 128]
        return out


