        r0 = F.relu(n0)  # expected-shape: r0=[b361, 16, 28, 28]
        p0 = self.pool(r0)  # expected-shape: p0=[b361, 16, 14, 14]
        c1 = self.conv1(p0)  # expected-shape: c1=[b361, 32, 10, 10]
        n1 = self.bn1(c1)  # expected-shape: n1=[b361, 32, 10, 10]
        r1 = F.relu(n1)  # expected-shape: r1=[b361, 32, 10, 10]
        p1 = self.pool(r1)  # expected-shape: p1=[b361, 32, 5, 5]
        c2 = self.conv2(p1)  # expected-shape: c2=[b361, 96, 5, 5]
        n2 = self.bn2(c2)  # expected-shape: n2=[b361, 96, 5, 5]
        r2 = F.relu(n2)  # expected-shape: r2=[b361, 96, 5, 5]
        p2 = self.pool(r2)  # expected-shape: p2=[b361, 96, 2, 2]
        f = p2.flatten(1)  # expected-shape: f=[b361, 384]
        logits = self.fc(f)  # expected-shape: logits=[b361, 100]
        return logits


