def cross_375(x: Float[Array, "b375 d375"], w: Float[Array, "d375 k375"], seq: Float[Array, "b375 n375 d375"]):
    a = norm_rows_15(x)  # expected-shape: a=[b375, d375]
    p = project_15(a, w)  # expected-shape: p=[b375, k375]
    c = pool_seq_15(seq)  # expected-shape: c=[b375, d375]
    q = project_15(c, w)  # expected-shape: q=[b375, k375]
    sc = attend_15(seq, seq)  # expected-shape: sc=[b375, n375, n375]
    s2 = scale_rows_15(sc)  # expected-shape: s2=[b375, n375, n375]
    return p, q, s2


class EqxBlock376(eqx.Module):
    w1: eqx.nn.Linear
    w2: eqx.nn.Linear
    norm: eqx.nn.LayerNorm

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.w1 = eqx.nn.Linear(32, 64, key=k1)
        self.w2 = eqx.nn.Linear(64, 32, key=k2)
        self.norm = eqx.nn.LayerNorm(32)

    def __call__(self, x: Float[Array, "s376 32"]):
        h = jax.vmap(self.w1)(x)  # expected-shape: h=[s376, 64]
        h = jax.nn.gelu(h)  # expected-shape: h=[s376, 64]
        h = jax.vmap(self.w2)(h)  # expected-shape: h=[s376, 32]
        r = x + h  # expected-shape: r=[s376, 32]
        y = jax.vmap(self.norm)(r)  # expected-shape: y=[s376, 32]
        return y


