def branchy_386(x: Float[Array, "b386 n386 d386"], y: Float[Array, "b386 n386 d386"], flag386: bool):
    z = x + y  # expected-shape: z=[b386, n386, d386]
    if flag386:
        w = z.sum(axis=-1)  # expected-shape: w=[b386, n386]
    elif not flag386:
        w = z.mean(axis=1)  # expected-shape: w=[b386, d386]
    else:
        w = z[:, :, 0]  # expected-shape: w=[b386, n386]
    for _ in range(3):
        z = z * 0.5  # expected-shape: z=[b386, n386, d386]
    try:
        q = z.sum(axis=0)  # expected-shape: q=[n386, d386]
    except ValueError:
        q = z.mean(axis=0)  # expected-shape: q=[n386, d386]
    with jax.default_device(None):
        s = q.sum()  # expected-shape: s=[]
    helper = lambda t: t + 1
    return w, q, s


def scan_ema_387(xs: Float[Array, "t387 16"], h0: Float[Array, "16"]):
    def body(carry, x):
        new = carry * 0.9 + x * 0.1
        return new, new * 2.0

    last, ys = jax.lax.scan(body, h0, xs)  # expected-shape: last=[16]; ys=[t387, 16]
    total = ys.sum(axis=0)  # expected-shape: total=[16]
    scaled = ys / 2.0  # expected-shape: scaled=[t387, 16]
    return last, scaled


def vmap_rows_387(x: Float[Array, "b387 t387 16"], w: Float[Array, "16 12"]):
    y = jax.vmap(lambda r: r @ w)(x)  # expected-shape: y=[b387, t387, 12]
    z = jax.vmap(jnp.sum)(x)
    e = jnp.einsum('btd,dk->btk', x, w)  # expected-shape: e=[b387, t387, 12]
    m = jnp.mean(e, axis=1)  # expected-shape: m=[b387, 12]
    mm = jnp.max(e, axis=(0, 1))  # expected-shape: mm=[12]
    return y, z, m


class ConvNet388(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv0 = nn.Conv2d(1, 24, 3, stride=1, padding=0)
        self.bn0 = nn.BatchNorm2d(24)
        self.conv1 = nn.Conv2d(24, 32, 5, stride=1, padding=2)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 64, 5, stride=2, padding=2)
        self.bn2 = nn.BatchNorm2d(64)
        self.pool = nn.MaxPool2d(2)
        self.fc = nn.Linear(256, 10)

    def forward(self, x: Float[Array, "b388 1 32 32"]):
        c0 = self.conv0(x)  # expected-shape: c0=[b388, 24, 30, 30]
        n0 = self.bn0(c0)  # expected-shape: n0=[b388, 24, 30, 30]
        r0 = F.relu(n0)  # expected-shape: r0=[b388, 24, 30, 30]
        p0 = self.pool(r0)  # expected-shape: p0=[b388, 24, 15, 15]
        c1 = self.conv1(p0)  # expected-shape: c1=[b388, 32, 15, 15]
        n1 = self.bn1(c1)  # expected-shape: n1=[b388, 32, 15, 15]
        r1 = F.relu(n1)  # expected-shape: r1=[b388, 32, 15, 15]
        p1 = self.pool(r1)  # expected-shape: p1=[b388, 32, 7, 7]
        c2 = self.conv2(p1)  # expected-shape: c2=[b388, 64, 4, 4]
        n2 = self.bn2(c2)  # expected-shape: n2=[b388, 64, 4, 4]
        r2 = F.relu(n2)  # expected-shape: r2=[b388, 64, 4, 4]
        p2 = self.pool(r2)  # expected-shape: p2=[b388, 64, 2, 2]
        f = p2.flatten(1)  # expected-shape: f=[b388, 256]
        logits = self.fc(f)  # expected-shape: logits=[b388, 10]
        return logits


