def long_chain_412(x: Float[Array, "b412 16 d412"]):
    v0 = jnp.swapaxes(x, 0, 2)  # expected-shape: v0=[d412, 16, b412]
    v1 = jnp.expand_dims(v0, axis=2)
    v2 = jnp.max(v1, axis=1)
