    v4 = jnp.swapaxes(v3, 0, 2)
    v5 = v4[:, 0]  # expected-shape: v5=[b412, d412]
    v6 = jax.nn.relu(v5)
    v7 = jax.nn.relu(v6)
    v8 = v7 * 0.5
    v9 = jnp.abs(v8)
    v10 = v9 * 1.5  # expected-shape: v10=[b412, d412]
    v11 = jnp.abs(v10)
    v12 = v11 * 1.5
    v13 = jax.nn.sigmoid(v12)
    v14 = v13 + v6
    v15 = v14 * 2.0  # expected-shape: v15=[b412, d412]
    v16 = v15 + v5
    v17 = jax.nn.relu(v16)
    v18 = jnp.expand_dims(v17, axis=0)
    v19 = jax.nn.gelu(v18)
    v20 = jnp.expand_dims(v19, axis=3)  # expected-shape: v20=[1, b412, d412, 1]
    v21 = v20.mean(axis=1)
    v22 = jnp.exp(v21)
    v23 = v22 + v22
    v24 = v23.T
    v25 = v24.T  # expected-shape: v25=[1, d412, 1]
    v26 = jnp.expand_dims(v25, axis=2)
    v27 = v26 * 0.5
    v28 = v27 * 0.5
    v29 = v28 + v27
    v30 = jnp.swapaxes(v29, 2, 3)  # expected-shape: v30=[1, d412, 1, 1]
    v31 = jax.nn.softmax(v30, axis=-1)
    v32 = jnp.swapaxes(v31, 0, 2)
    v33 = jax.nn.relu(v32)
    v34 = jax.nn.sigmoid(v33)
    v35 = jnp.concatenate([v34, v34], axis=3)  # expected-shape: v35=[1, d412, 1, 2]
    v36 = jnp.exp(v35)
    v37 = jnp.max(v36, axis=2)
    v38 = jnp.exp(v37)
    v39 = v38.sum(axis=2)
    v40 = jnp.expand_dims(v39, axis=0)  # expected-shape: v40=[1, 1, d412]
    v41 = jnp.concatenate([v40, v40], axis=1)
    v42 = jnp.swapaxes(v41, 0, 2)
    v43 = v42.sum(axis=1)
