def einops_soup_413(x: Float[Array, "b413 n413 32"]):
    e0 = rearrange(x, "b ... d -> d b ...")  # expected-shape: e0=[32, b413, n413]
    e1 = rearrange(x, "b n d -> (b n) d")  # expected-shape: e1=[b413*n413, 32]
    e2 = rearrange(x, "b n (h e) -> b h n e", h=4)  # expected-shape: e2=[b413, 4, n413, 8]
    e3 = reduce(x, "b n d -> n", "sum")  # expected-shape: e3=[n413]
    e_two = rearrange(x, "... n ... -> ... n")  # expected-shape: e_two=?
    return e0


class EqxBlock414(eqx.Module):
    w1: eqx.nn.Linear
    w2: eqx.nn.Linear
    norm: eqx.nn.LayerNorm

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.w1 = eqx.nn.Linear(64, 128, key=k1)
        self.w2 = eqx.nn.Linear(128, 64, key=k2)
        self.norm = eqx.nn.LayerNorm(64)

    def __call__(self, x: Float[Array, "s414 64"]):
        h = jax.vmap(self.w1)(x)  # expected-shape: h=[s414, 128]
        h = jax.nn.gelu(h)  # expected-shape: h=[s414, 128]
        h = jax.vmap(self.w2)(h)  # expected-shape: h=[s414, 64]
        r = x + h  # expected-shape: r=[s414, 64]
        y = jax.vmap(self.norm)(r)  # expected-shape: y=[s414, 64]
        return y


class EqxModel414(eqx.Module):
    blk: EqxBlock414
    head: eqx.nn.Linear

    def __init__(self, key):
        k1, k2 = jax.random.split(key)
        self.blk = EqxBlock414(k1)
        self.head = eqx.nn.Linear(64, 10, key=k2)

    def __call__(self, x: Float[Array, "s414 64"]):
        h = self.blk(x)  # expected-shape: h=[s414, 64]
        p = jax.vmap(self.head)(h)  # expected-shape: p=[s414, 10]
        m = p.mean(axis=0)  # expected-shape: m=[10]
        return m


