class Attn423(nn.Module):
    def __init__(self):
        super().__init__()
        self.qkv_423 = nn.Linear(64, 192)
        self.proj_423 = nn.Linear(64, 64)
        self.norm_423 = nn.LayerNorm(64)

    def forward(self, x: Float[Array, "b423 s423 64"]):
        qkv = self.qkv_423(x)  # expected-shape: qkv=[b423, s423, 192]
        q, k, v = qkv.chunk(3, dim=-1)  # expected-shape: q=[b423, s423, 64]; k=[b423, s423, 64]; v=[b423, s423, 64]
        q = q.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: q=[b423, s423, 2, 32]
        k = k.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: k=[b423, s423, 2, 32]
        v = v.reshape(x.shape[0], x.shape[1], 2, 32)  # expected-shape: v=[b423, s423, 2, 32]
        q = q.permute(0, 2, 1, 3)  # expected-shape: q=[b423, 2, s423, 32]
        k = k.permute(0, 2, 3, 1)  # expected-shape: k=[b423, 2, 32, s423]
        v = v.permute(0, 2, 1, 3)  # expected-shape: v=[b423, 2, s423, 32]
        scores = q @ k  # expected-shape: scores=[b423, 2, s423, s423]
        attn = F.softmax(scores, dim=-1)  # expected-shape: attn=[b423, 2, s423, s423]
        ctx = attn @ v  # expected-shape: ctx=[b423, 2, s423, 32]
        ctx = ctx.permute(0, 2, 1, 3)  # expected-shape: ctx=[b423, s423, 2, 32]
        ctx = ctx.reshape(x.shape[0], x.shape[1], 64)  # expected-shape: ctx=[b423, s423, 64]
        out = self.proj_423(ctx)  # expected-shape: out=[b423, s423, 64]
        out = self.norm_423(out + x)  # expected-shape: out=[b423, s423, 64]
        return out


