    r2 = reduce_last_468(y)  # expected-shape: r2=[n468]
    r3 = reduce_last_468(z)  # expected-shape: r3=[]
    r4 = reduce_last_468(x) + 1.0  # expected-shape: r4=[b468, n468]
    return r1, r2, r3, r4


