def scalar_operands_497(ys: Float[Array, "t497 d497"], zs: Float[Array, "t497"], k: int):
    a = ys / jnp.sqrt(2.0)  # expected-shape: a=[t497, d497]
    b = ys / math.sqrt(k)  # expected-shape: b=[t497, d497]
    c = ys * math.pi  # expected-shape: c=[t497, d497]
    e = ys / len(zs)  # expected-shape: e=[t497, d497]
    f = ys / (2 * jnp.sqrt(2.0))  # expected-shape: f=[t497, d497]
    g = ys / ys.shape[-1]  # expected-shape: g=[t497, d497]
    dk = ys.shape[-1]
    inv = 1.0 / math.sqrt(dk)
    h = ys * inv  # expected-shape: h=[t497, d497]
