def branch_merge_503(x: Float[Array, "b503 n503 d503"], flag: bool):
    if flag:
        v = x.sum(axis=-1)  # expected-shape: v=[b503, n503]
    else:
        v = x[:, :, 0]  # expected-shape: v=[b503, n503]
    u = v * 2.0  # expected-shape: u=[b503, n503]
    if flag:
        w = x.sum(axis=-1)  # expected-shape: w=[b503, n503]
    else:
        w = x.sum(axis=1)  # expected-shape: w=[b503, d503]
    r = w + 1.0  # expected-shape: r=?
    s = x
    if flag:
        s = x.sum(axis=0)  # expected-shape: s=[n503, d503]
    t = s * 2.0  # expected-shape: t=?
    if flag:
        g = x.sum(axis=1)  # expected-shape: g=[b503, d503]
    h = g * 2.0  # expected-shape: h=[b503, d503]
    p = x
    if flag:
        p = x.sum(axis=0)  # expected-shape: p=[n503, d503]
        return p
    q = p * 2.0  # expected-shape: q=[b503, n503, d503]
    lp = x
    for _ in range(3):
        lp = x.sum(axis=0)  # expected-shape: lp=[n503, d503]
    lq = lp * 1.0  # expected-shape: lq=?
    try:
        ta = x.sum(axis=0)  # expected-shape: ta=[n503, d503]
    except ValueError:
        ta = x.sum(axis=1)  # expected-shape: ta=[b503, d503]
    tb = ta * 2.0  # expected-shape: tb=?
    try:
        tc = x.sum(axis=0)  # expected-shape: tc=[n503, d503]
    except ValueError:
        raise
    td = tc * 2.0  # expected-shape: td=[n503, d503]
    match flag:
        case True:
            ma = x.sum(axis=-1)  # expected-shape: ma=[b503, n503]
        case _:
            ma = x[:, :, 0]  # expected-shape: ma=[b503, n503]
    mb = ma + 1.0  # expected-shape: mb=[b503, n503]
    return u, r, t, h, q, lq, tb, td, mb


